function source(){if(!current())return;const c=current(),b=bookFor(c);$('#dialogTitle').textContent=b.title;$('#dialogPages').textContent=(c.pages.length?'Buchseite '+c.pages.join(', '):'Eingefügte Passage')+(c.pdfPages.length?' · PDF-Seite '+c.pdfPages.join(', '):'');$('#sourceText').textContent=c.source;showDialog('#sourceDialog');}
function renderBooks(){$('#bookCount').textContent=state.books.length;$('#booksGrid').innerHTML=state.books.map(b=>`<article class="book-card"><div class="book-cover">${escape(b.title.slice(0,28))}</div><h3>${escape(b.title)}</h3><p>${escape(b.author||'Eigener Import')}<br>${escape(b.edition||'Originalpassagen')}</p><p>${b.clips.length.toLocaleString('de')} Clips${b.pageCount?' · '+b.pageCount+' PDF-Seiten':''}</p><div class="book-card-footer"><label class="switch-label"><input type="checkbox" data-toggle-book="${escape(b.id)}" ${state.disabled.includes(b.id)?'':'checked'}> Im Feed aktiv</label><span class="tiny">${adminDemo?'Nur lokal · Admin-Test':'Privat im Konto'}</span></div><div class="book-actions"><button class="text-button" data-export-book="${escape(b.id)}">↓ Clip-Paket</button><button class="text-button" data-export-markdown="${escape(b.id)}">↓ Markdown</button><button class="text-button" data-remove-book="${escape(b.id)}">Buch löschen</button></div></article>`).join('');renderFocusOptions();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function sourceBooks(){return state.books.filter(b=>!b.generatedFrom&&b.clips.some(c=>c.source&&c.kind!=='focus'));}
function focusSources(book,topic=''){const preferred=book.clips.filter(c=>c.kind==='excerpt'&&c.source&&(!topic||c.category===topic));return preferred.length?preferred:book.clips.filter(c=>c.kind!=='focus'&&c.source&&(!topic||c.category===topic));}
function usedFocusSourceIds(bookId){return new Set(state.books.flatMap(b=>b.clips).filter(c=>c.kind==='focus'&&c.originBookId===bookId&&c.sourceClipId).map(c=>c.sourceClipId));}
function focusCandidates(book,topic=''){const used=usedFocusSourceIds(book.id),treatedPages=new Set(book.clips.filter(c=>c.kind==='editorial').flatMap(c=>c.pages||[])),focusAll=state.books.flatMap(b=>b.clips).filter(c=>c.kind==='focus'&&c.originBookId===book.id),categoryCounts=new Map();for(const c of [...book.clips.filter(c=>c.kind==='editorial'),...focusAll])categoryCounts.set(c.category,(categoryCounts.get(c.category)||0)+1);return focusSources(book,topic).filter(c=>!used.has(c.id)).sort((a,b)=>{const ap=(a.pages||[]).some(p=>treatedPages.has(p))?1:0,bp=(b.pages||[]).some(p=>treatedPages.has(p))?1:0;if(ap!==bp)return ap-bp;const ac=categoryCounts.get(a.category)||0,bc=categoryCounts.get(b.category)||0;if(ac!==bc)return ac-bc;return ((a.pages||[99999])[0]||99999)-((b.pages||[99999])[0]||99999);});}
function renderFocusOptions(){const bookSel=$('#focusBook');if(!bookSel)return;const books=sourceBooks(),previous=bookSel.value;bookSel.innerHTML=books.map(b=>`<option value="${escape(b.id)}">${escape(b.title)}</option>`).join('');if(books.some(b=>b.id===previous))bookSel.value=previous;const book=books.find(b=>b.id===bookSel.value)||books[0];const topicSel=$('#focusTopic');if(!book){topicSel.innerHTML='<option value="">Keine Quelle verfügbar</option>';$('#focusAvailable').textContent='';$('#generateFocus').disabled=true;return;}const topicPrevious=topicSel.value,topics=[...new Set(focusSources(book).map(c=>c.category))].sort((a,b)=>a.localeCompare(b,'de'));topicSel.innerHTML='<option value="">Automatisch: Lücken zuerst</option>'+topics.map(t=>`<option value="${escape(t)}">${escape(t)}</option>`).join('');if(topics.includes(topicPrevious))topicSel.value=topicPrevious;const n=focusCandidates(book,topicSel.value).length;$('#focusAvailable').textContent=n.toLocaleString('de')+' Quellabschnitte sind in dieser Auswahl noch nicht als Fokusclip verwendet.';$('#focusCount').max=Math.max(1,Math.min(n,1500));$('#focusCount').value=Math.min(Math.max(1,Number($('#focusCount').value)||20),Math.max(1,Math.min(n,1500)));$('#generateFocus').disabled=n===0;}
