$('#uploadMedia').onclick=async()=>{const c=current(),file=$('#mediaFile').files[0];if(!c||!file)return $('#mediaStatus').textContent='Bitte eine Videodatei auswählen.';if(file.size>1_500_000_000)return $('#mediaStatus').textContent='Die Datei ist größer als 1,5 GB.';const btn=$('#uploadMedia'),oldRef=c.videoRef?{...c.videoRef}:null,oldUrl=c.videoUrl;btn.disabled=true;$('#mediaProgress').hidden=false;$('#mediaStatus').textContent='Video wird auf den Pi hochgeladen …';let uploaded=null;try{uploaded=await media.upload(file);c.videoRef={provider:'pi',mediaId:uploaded.media_id,name:file.name};delete c.videoUrl;const b=bookFor(c);await saveBook(b);if(oldRef?.provider==='pi'&&oldRef.mediaId&&oldRef.mediaId!==uploaded.media_id)media.remove(oldRef.mediaId).catch(()=>{});$('#mediaStatus').textContent='Video verknüpft.';$('#detachMedia').hidden=false;prepareRealVideo(c);toast('Echtes Video verknüpft.');}catch(e){if(oldRef)c.videoRef=oldRef;else delete c.videoRef;if(oldUrl)c.videoUrl=oldUrl;if(uploaded?.media_id)media.remove(uploaded.media_id).catch(()=>{});$('#mediaStatus').textContent=e.message;}finally{btn.disabled=!media.enabled();$('#mediaProgress').hidden=true;}};
