$('#uploadGeneratedVideos').onclick=async()=>{const files=[...$('#generatedVideoFiles').files];const status=$('#generatedVideoStatus'),progress=$('#generatedVideoProgress');if(!files.length){status.textContent='Bitte zuerst die vom PC-Generator erzeugten MP4-Dateien auswählen.';return;}if(adminDemo){status.textContent='Der lokale Admin-Testmodus kann keine Pi-Videos hochladen. Bitte normal anmelden.';return;}if(!media.enabled()){status.textContent='Der Pi-Medienserver ist noch nicht konfiguriert. Die MP4s können bis dahin lokal bleiben.';return;}const btn=$('#uploadGeneratedVideos');btn.disabled=true;progress.hidden=false;progress.value=0;const changed=new Set(),oldToDelete=[];let linked=0,skipped=0;try{for(let i=0;i<files.length;i++){const file=files[i],clipId=file.name.replace(/\.mp4$/i,'');let found=null,book=null;for(const b of state.books){const c=b.clips.find(c=>String(c.id)===clipId);if(c){found=c;book=b;break;}}if(!found){skipped++;status.textContent=`${i+1}/${files.length}: Keine Clip-ID für ${file.name} gefunden.`;progress.value=(i+1)/files.length;continue;}status.textContent=`${i+1}/${files.length}: ${file.name} wird hochgeladen …`;const uploaded=await media.upload(file);if(found.videoRef?.provider==='pi'&&found.videoRef.mediaId)oldToDelete.push(found.videoRef.mediaId);found.videoRef={provider:'pi',mediaId:uploaded.media_id,name:file.name};delete found.videoUrl;changed.add(book);linked++;progress.value=(i+1)/files.length;}for(const b of changed)await api('/api/books/'+b.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});for(const id of oldToDelete)media.remove(id).catch(()=>{});rebuild(true);status.textContent=`Fertig: ${linked} Videos verknüpft${skipped?`, ${skipped} ohne passende Clip-ID übersprungen`:''}.`;toast(linked+' echte Videos verknüpft.');}catch(e){status.textContent='Upload abgebrochen: '+e.message;}finally{btn.disabled=false;progress.hidden=true;}};
// Real video files: 720 × 1280 canvas capture; explicitly silent.
$('#exportCurrent').onclick=()=>{if(!current())return;$('#videoCount').value=1;$('#videoCount').max=Math.min(state.pool.length,100);$('#downloadVideo').hidden=true;$('#exportStatus').textContent='';showDialog('#videoDialog');};
// The export is also reachable from the source dialog on small screens.
const mobileExport=document.createElement('button');mobileExport.className='text-button';mobileExport.textContent='↓ Diesen Clip als Video';mobileExport.onclick=()=>{$('#sourceDialog').close();$('#exportCurrent').click();};$('#sourceDialog').append(mobileExport);const mobileMedia=document.createElement('button');mobileMedia.className='text-button';mobileMedia.textContent='▻ Echtes Video verknüpfen';mobileMedia.onclick=()=>{$('#sourceDialog').close();$('#attachMedia').click();};$('#sourceDialog').append(mobileMedia);
$('#cancelExport').onclick=()=>{exportCancelled=true;};
function wrap(ctx,text,maxWidth){let lines=[],line='';for(const w of text.split(/\s+/)){const next=line?line+' '+w:w;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=w;}else line=next;}if(line)lines.push(line);return lines;}
function drawFrame(ctx,c,s,pct,img){const w=720,h=1280;ctx.fillStyle=s.label==='Denk kurz nach'?'#49312b':c.kind==='excerpt'?'#253344':'#233f38';ctx.fillRect(0,0,w,h);ctx.fillStyle='#c6f567';ctx.font='bold 23px sans-serif';ctx.fillText('HISTOSCROLL',52,65);ctx.fillStyle='#c9d6c8';ctx.font='22px sans-serif';ctx.fillText(c.category.slice(0,42),52,108);let y=160;if(img){const hh=250;ctx.save();ctx.beginPath();ctx.rect(52,y,616,hh);ctx.clip();const scale=Math.max(616/img.width,hh/img.height)*(1+pct*.025);ctx.drawImage(img,52+(616-img.width*scale)/2,y+(hh-img.height*scale)/2,img.width*scale,img.height*scale);ctx.restore();y+=hh+48;}else y=250;ctx.fillStyle='#c6f567';ctx.font='bold 21px sans-serif';ctx.fillText(s.label.toUpperCase().slice(0,48),52,y);y+=60;ctx.fillStyle='#f1f3e9';ctx.font='bold 46px sans-serif';for(const l of wrap(ctx,c.title,606).slice(0,4)){ctx.fillText(l,52,y);y+=53;}y+=25;let size=34,lines;do{ctx.font=size+'px sans-serif';lines=wrap(ctx,s.text,606);if(y+lines.length*size*1.42<1090)break;size-=1;}while(size>21);ctx.fillStyle='#e6eadf';for(const l of lines){ctx.fillText(l,52,y);y+=size*1.42;}ctx.fillStyle='#ffffff35';ctx.fillRect(52,1150,616,5);ctx.fillStyle='#c6f567';ctx.fillRect(52,1150,616*pct,5);ctx.font='20px sans-serif';ctx.fillStyle='#c9d6c8';ctx.fillText((bookFor(c)?.title||'Lehrbuch').slice(0,49),52,1200);ctx.fillText(c.pages.length?'Buchseite '+c.pages.join(', '):'Eingefügte Passage',52,1234);}
async function recordClip(c){const canvas=document.createElement('canvas');canvas.width=720;canvas.height=1280;const ctx=canvas.getContext('2d');let img=null;if(c.image){img=new Image();img.src=c.image;try{await img.decode();}catch{img=null;}}const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('WebM-Export wird von diesem Browser nicht unterstützt. Nutze Chrome oder Firefox am Computer.');drawFrame(ctx,c,c.scenes[0],0,img);const stream=canvas.captureStream(25),rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:1400000});const parts=[];rec.ondataavailable=e=>{if(e.data.size)parts.push(e.data);};const done=new Promise((resolve,reject)=>{rec.onstop=()=>resolve(new Blob(parts,{type:'video/webm'}));rec.onerror=()=>reject(Error('Videoaufnahme fehlgeschlagen.'));});rec.start();let elapsed=0,previous=performance.now(),raf;const durations=c.scenes.map(duration),total=durations.reduce((a,b)=>a+b,0);await new Promise(resolve=>{const frame=now=>{elapsed+=Math.min((now-previous)/1000,.2);previous=now;if(exportCancelled||elapsed>=total){resolve();return;}let scene=0,left=elapsed;while(scene<durations.length-1&&left>durations[scene]){left-=durations[scene];scene++;}drawFrame(ctx,c,c.scenes[scene],elapsed/total,scene<3?img:null);raf=requestAnimationFrame(frame);};raf=requestAnimationFrame(frame);});cancelAnimationFrame(raf);rec.stop();const blob=await done;stream.getTracks().forEach(t=>t.stop());return blob;}
// ZIP STORE writer (no dependency, CRC32 for interoperable archives).
function zipStore(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;const crc32=a=>{let c=-1;for(const v of a){c^=v;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^-1)>>>0;};for(const f of files){const name=enc.encode(f.name),crc=crc32(f.data),head=new Uint8Array(30+name.length),h=new DataView(head.buffer);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint32(14,crc,true);h.setUint32(18,f.data.length,true);h.setUint32(22,f.data.length,true);h.setUint16(26,name.length,true);head.set(name,30);parts.push(head,f.data);const ch=new Uint8Array(46+name.length),v=new DataView(ch.buffer);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x800,true);v.setUint32(16,crc,true);v.setUint32(20,f.data.length,true);v.setUint32(24,f.data.length,true);v.setUint16(28,name.length,true);v.setUint32(42,offset,true);ch.set(name,46);central.push(ch);offset+=head.length+f.data.length;}const size=central.reduce((s,x)=>s+x.length,0),end=new Uint8Array(22),d=new DataView(end.buffer);d.setUint32(0,0x06054b50,true);d.setUint16(8,files.length,true);d.setUint16(10,files.length,true);d.setUint32(12,size,true);d.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
$('#startExport').onclick=async()=>{if(exporting)return;const n=Number($('#videoCount').value);if(!Number.isInteger(n)||n<1||n>Math.min(state.pool.length,100)){toast('Bitte eine gültige Anzahl wählen.');return;}if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){$('#exportStatus').textContent='Dieser Browser unterstützt den Videoexport nicht. Bitte Chrome oder Firefox am Computer nutzen.';return;}exporting=true;exportCancelled=false;$('#startExport').disabled=true;$('#cancelExport').hidden=false;$('#downloadVideo').hidden=true;$('#exportProgress').hidden=false;$('#exportProgress').value=0;const clips=[current(),...state.pool.filter(c=>c.id!==current().id)].slice(0,n),files=[];try{for(let i=0;i<clips.length;i++){if(exportCancelled)break;$('#exportStatus').textContent='Rendere Video '+(i+1)+' / '+n+' …';const blob=await recordClip(clips[i]);if(exportCancelled)break;files.push({name:String(i+1).padStart(3,'0')+'-HistoScroll.webm',data:new Uint8Array(await blob.arrayBuffer())});$('#exportProgress').value=(i+1)/n;}if(exportCancelled){$('#exportStatus').textContent='Export abgebrochen.';}else{const blob=n===1?new Blob([files[0].data],{type:'video/webm'}):zipStore(files);if(exportUrl)URL.revokeObjectURL(exportUrl);exportUrl=URL.createObjectURL(blob);$('#downloadVideo').href=exportUrl;$('#downloadVideo').download=n===1?'HistoScroll.webm':'HistoScroll-Videos.zip';$('#downloadVideo').hidden=false;$('#exportStatus').textContent=n+' Video'+(n>1?'s':'')+' fertig · ohne Ton.';}}catch(e){$('#exportStatus').textContent=e.message;}finally{exporting=false;$('#startExport').disabled=false;$('#cancelExport').hidden=true;}};
